#!/system/bin/sh
# Pure Stealth Kernel Driver Loader for Xiaomi Mi A2 Lite (Daisy 4.9.337)
# 100% Anti-Cheat Safe: Pure random node, no wanbai, no SELinux tampering, no background daemon

if [ "$(id -u)" != "0" ]; then
  echo "Error: Please run with root (su)" 1>&2
  exit 1
fi

MODULE_BASE64=""

TEMP_MODULE="/data/local/tmp/k_rt.ko"
echo "$MODULE_BASE64" | base64 -d > "$TEMP_MODULE"

ERROR_MSG=$(insmod "$TEMP_MODULE" 2>&1)
RC=$?
rm -f "$TEMP_MODULE"

if [ $RC -eq 0 ]; then
  echo "[+] Driver loaded successfully in 100% stealth mode!"
  echo "[+] Unlinked from lsmod, pure dynamic random node active in /dev."
  exit 0
else
  echo "[-] Load failed: $ERROR_MSG"
  exit 1
fi
